Here is a simple C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

```cpp
#include <iostream>
#include <fstream>
#include <string>

int main() {
    std::string filename, word, line;
    std::string searchWord;
    int count = 0;

    // Get the filename and the word to search for from user input
    std::cout << "Enter the filename: ";
    std::cin >> filename;
    std::cout << "Enter the word to search for: ";
    std::cin >> searchWord;

    // Open the file for reading
    std::ifstream file(filename);

    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return 1;
    }

    // Read the file line by line
    while (std::getline(file, line)) {
        // Reset the string stream for the current line
        std::stringstream ss(line);
        std::string token;

        // Search for the word in each token of the current line
        while (ss >> token) {
            if (token == searchWord) {
                count++;
            }
        }
    }

    // Close the file
    file.close();

    // Print the result
    std::cout << "The word '" << searchWord << "' occurs " << count << " times in the file." << std::endl;

    return 0;
}
```

